Here's a modern MSTest test class for your `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _sut;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        var client = new HttpClient(_handler) { BaseAddress = new Uri("https://example.com") };
        _sut = new DataFetcher(client);
    }

    [TestMethod]
    public async Task FetchAsync_SuccessfulResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";

        // Act
        var result = await _sut.FetchAsync("https://example.com/data", _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_WithTimeout_CompletesWithinLimit()
    {
        _handler.ResponseContent = "fast response";

        var result = await _sut.FetchAsync("https://example.com/data", _testContext.CancellationToken);

        Assert.IsNotNull(result);
    }

    [TestMethod]
    public async Task FetchAsync_CancellationRequested_ThrowsTaskCanceledException()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _sut.FetchAsync("https://example.com/data", cts.Token));
    }

    [TestMethod]
    public async Task FetchAsync_ServerError_ThrowsHttpRequestException()
    {
        _handler.StatusCode = System.Net.HttpStatusCode.InternalServerError;

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _sut.FetchAsync("https://example.com/data", _testContext.CancellationToken));
    }

    [TestMethod]
    [DataRow("https://example.com/a")]
    [DataRow("https://example.com/b")]
    public async Task FetchAsync_MultipleUrls_ReturnsContent(string url)
    {
        _handler.ResponseContent = "data";

        var result = await _sut.FetchAsync(url, _testContext.CancellationToken);

        Assert.AreEqual("data", result);
    }
}
```

And the test helper:

```csharp
internal sealed class MockHttpMessageHandler : HttpMessageHandler
{
    public string ResponseContent { get; set; } = string.Empty;
    public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;

    protected override Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        var response = new HttpResponseMessage(StatusCode)
        {
            Content = new StringContent(ResponseContent)
        };
        return Task.FromResult(response);
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---------|-----|
| **Async tests** | `async Task` return type — MSTest awaits natively |
| **Timeouts** | `[Timeout(5000)]` + flow `_testContext.CancellationToken` into the call |
| **Cancellation** | Create a pre-cancelled `CancellationTokenSource`, assert `ThrowsExactlyAsync<TaskCanceledException>` |
| **Exception testing** | `Assert.ThrowsExactlyAsync<T>` instead of `[ExpectedException]` |
| **Lifecycle** | Constructor injection of `TestContext` (MSTest 3.6+), `readonly` fields |

The critical detail: always pass `_testContext.CancellationToken` to your async calls so that `[Timeout]` can cooperatively cancel the test if it hangs.
